CREATE DATABASE IF NOT EXISTS campushub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campushub;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','faculty','admin') NOT NULL DEFAULT 'student',department VARCHAR(120) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,domain VARCHAR(100) DEFAULT 'General',deadline DATE NULL,status ENUM('open','in_progress','completed','closed') DEFAULT 'open',created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS submissions(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,student_id INT NOT NULL,submission_url VARCHAR(500) DEFAULT '',description TEXT,status ENUM('submitted','approved','needs_revision','rejected') DEFAULT 'submitted',faculty_feedback TEXT,grade DECIMAL(5,2) NULL,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_project_student(project_id,student_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,due_date DATE NULL,assigned_to INT NULL,created_by INT NOT NULL,priority ENUM('low','medium','high') DEFAULT 'medium',status ENUM('pending','in_progress','completed') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skills(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,level ENUM('beginner','intermediate','advanced') DEFAULT 'beginner',proof_url VARCHAR(500) DEFAULT '',verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS certifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,issuer VARCHAR(180) NOT NULL,issue_date DATE NULL,credential_url VARCHAR(500) DEFAULT '',verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS feedback(id INT AUTO_INCREMENT PRIMARY KEY,from_user INT NOT NULL,to_user INT NOT NULL,task_id INT NULL,rating TINYINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comments TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(from_user) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(to_user) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE SET NULL);
